class Solution {
    public Node lowestCommonAncestor(Node p, Node q) {
        Node p1 = p;
        Node p2 = q;
        while (p1 != p2) {
            p1 = (p1 != null) ? p1.parent : q;
            p2 = (p2 != null) ? p2.parent : p;
        }
        return p1;
    }
}

var lowestCommonAncestor = function(p, q) {
    let p1 = p, p2 = q;
    while (p1 !== p2) {
        p1 = p1 ? p1.parent : q;
        p2 = p2 ? p2.parent : p;
    }
    return p1;
};
